import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"58、【兌】 兌下兌上","description":"周易尚氏學 - 58、【兌】 兌下兌上","frontmatter":{"title":"58、【兌】 兌下兌上","description":"周易尚氏學 - 58、【兌】 兌下兌上"},"headers":[],"relativePath":"classics/shangshi/063.md","filePath":"classics/shangshi/063.md"}'),s={name:"classics/shangshi/063.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_58、【兌】-兌下兌上" tabindex="-1">58、【兌】 兌下兌上 <a class="header-anchor" href="#_58、【兌】-兌下兌上" aria-label="Permalink to “58、【兌】 兌下兌上”">​</a></h1><p>兌悅也。兌何以悅。以一陰見於二陽之上。陽得陰而悅也。剛中柔外。與泰義合。故亨。陰陽相遇。故利貞。</p><p>彖曰。兌。說也。剛中而柔外。說以利是以順乎天而應乎人。說以先民。民忘其勞。說以犯難。民志其死。說之大。民功矣哉。</p><p>陰陽相遇故悅。悅故利貞。所謂保合太和。各正性命也。五天位。上順之。故日順乎天。互巽為順也。三人位。巽於二。故日應乎人。互巽為應也。三至上大坎。坎為民。為勞。為險難。為棺郭（左木）。故為死。而三至上正反兌。坎民來往。皆在兌說之中。故役之而忘勞。犯難而不知死也。兌見在上。故曰先民。先民說。先使民悅也。故民勸。</p><p>象曰。麗澤兌。君子以朋友講習。</p><p>玉篇麗偶也。周禮夏官校人。麗馬一口（內辛）。注麗耦也。又士冠禮。主人酬賓。束帛。儷皮。注儷皮兩鹿皮。古文儷作離。離傳雲。離而也。是麗一儷通仍耦也。重兌故曰麗澤。猶重巽日隨風。其以互離為義者。非也。陰陽相遇相悅為朋友。兌口故曰購習。初至五正反兌相對。正朋友互相講習之象。故君子法之。虞翻謂兌二陽同類為朋。夫陽遇陽。陰遇陰。則為害為敵。昆與中孚皆言之。豈得為朋友。又云伏艮為友。蓋取義於損六三。一人行則得其友。豈知艮之為友。以一陽上行。遇二陰為友。與兌之以一陰下降。遇二陽為朋友同。皆取義於陰陽相遇。朋友之詁既誤。於是卦無艮兌而言朋者。必百計變動以求兌象。甚至用參同契納甲之法。謂八日兌象月見了。以解坤彖之得朋。凡易之言朋者。無不誤矣。</p><p>初九。和兌，吉。</p><p>與二並行。故曰和。當位故吉。初與二本為敵。卦以兌說為義。和以處之。自然吉矣。</p><h3 id="象曰。和兌之吉。行未疑也。" tabindex="-1">象曰。和兌之吉。行未疑也。 <a class="header-anchor" href="#象曰。和兌之吉。行未疑也。" aria-label="Permalink to “象曰。和兌之吉。行未疑也。”">​</a></h3><p>初得敵。故疑於二。和以處之。故行不疑。損三雲。三則疑也。易於陽遇陽相疑相忌之故。言之至為明白矣。乃失傳何哉。</p><p>九二。孚兌吉。悔亡。</p><p>孚於三。陽遇陰故吉。得中。故悔亡。</p><h3 id="象曰。孚兌之吉。信志也。" tabindex="-1">象曰。孚兌之吉。信志也。 <a class="header-anchor" href="#象曰。孚兌之吉。信志也。" aria-label="Permalink to “象曰。孚兌之吉。信志也。”">​</a></h3><p>陽遇陰故志得伸。巽為志。三巽主爻。二遇之。故信志。</p><p>六三。來兌兇。</p><p>在內稱來。來就二陽以為悅。行為不正則有之。無所謂兇。但三本多兇。又不當位。來而不正遂不宜矣。</p><h3 id="象曰。來兌之兇。位不當也。" tabindex="-1">象曰。來兌之兇。位不當也。 <a class="header-anchor" href="#象曰。來兌之兇。位不當也。" aria-label="Permalink to “象曰。來兌之兇。位不當也。”">​</a></h3><p>來而不當位。故兇。</p><p>九四。商兌未寧。介疾有喜。</p><p>四不當位。無應。前又遇陽。似不吉。然而有喜者。以下履陰也。小畜九五曰有孚。履九四曰志行。皆以下遇陰而吉。此與之同。商量度也。商兌者以初至五正反兌相對。而四若與下對語者。故曰商兌。講習之象。亦以此也。三至五巽。進退不果。故未寧。互大坎為疾。乃四獨履陰。志行。是疾去也。介助也。詩以介眉壽是也。介疾有喜者。言助疾使愈。兌悅故有喜也。</p><h3 id="象曰。九四之喜。有慶也。" tabindex="-1">象曰。九四之喜。有慶也。 <a class="header-anchor" href="#象曰。九四之喜。有慶也。" aria-label="Permalink to “象曰。九四之喜。有慶也。”">​</a></h3><p>九四獨履陰。履陰故有喜。故曰有慶。</p><p>九五。孚於剝。有厲。</p><p>陽遇陰則通。故二五皆孚於三上。然吉凶不同者。兌為秋。六三當正秋。萬物成熟。故二孚之而吉。若上六則為季秋。其辰在戌。其卦為剝。雜卦雲。剝爛也。當此時萬物荒落。陽氣為陰所剝將盡矣。九五若再享於是。必為所剝無疑也。故曰有厲。</p><h3 id="象曰。孚於剝。位正當也。" tabindex="-1">象曰。孚於剝。位正當也。 <a class="header-anchor" href="#象曰。孚於剝。位正當也。" aria-label="Permalink to “象曰。孚於剝。位正當也。”">​</a></h3><p>以人事言。上六處悅之極。是小人佞悻之尤。九五當人君之位。而見近此等小人。其為禍有不可勝言者。象曰位正當。言正當人君之位。不可與上六近也。</p><p>上六。引兌。引。</p><p>開弓視的也。伏艮為手。故引兌。言上六來就五陽以為悅。猶射者之志於的也。</p><h3 id="象曰。上六引兌。未光也。" tabindex="-1">象曰。上六引兌。未光也。 <a class="header-anchor" href="#象曰。上六引兌。未光也。" aria-label="Permalink to “象曰。上六引兌。未光也。”">​</a></h3><p>兌門（內音）昧。故未光。</p>',30)])])}const f=e(s,[["render",t]]);export{_ as __pageData,f as default};
